static void red_capa(const float *x, int n_in, const float *W, const float *b,
                     int n_out, float *salida, int relu) {
  for (int j = 0; j < n_out; j++) {
    float z = b[j];
    for (int i = 0; i < n_in; i++) z += x[i] * W[i * n_out + j];
    salida[j] = (relu && z < 0.0f) ? 0.0f : z;
  }
}

/* Devuelve el gesto y su confianza (probabilidad softmax, 0 a 1) */
static int predecir_gesto(const float *x, float *confianza) {
  float a0[8];
  for (int i = 0; i < 8; i++) a0[i] = (x[i] - RED_MEDIA[i]) / RED_ESCALA[i];
  float a1[32];
  red_capa(a0, 8, &RED_W0[0][0], RED_B0, 32, a1, 1);
  float a2[16];
  red_capa(a1, 32, &RED_W1[0][0], RED_B1, 16, a2, 1);
  float a3[7];
  red_capa(a2, 16, &RED_W2[0][0], RED_B2, 7, a3, 0);
  int mejor = 0;
  for (int k = 1; k < NUM_CLASES; k++) if (a3[k] > a3[mejor]) mejor = k;
  float suma = 0.0f;
  for (int k = 0; k < NUM_CLASES; k++) suma += expf(a3[k] - a3[mejor]);
  if (confianza) *confianza = 1.0f / suma;
  return mejor;
}
